import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.apache.commons.text.StringEscapeUtils;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");
        String format = req.getParameter("fmt");

        // Input validation - sanitize for XSS in error messages
        String safeType = StringEscapeUtils.escapeHtml4(reportType);
        String safeDept = StringEscapeUtils.escapeHtml4(department);

        if (reportType == null || startDate == null || endDate == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate date format
        if (!startDate.matches("\\d{4}-\\d{2}-\\d{2}") || !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date format. Use YYYY-MM-DD");
            return;
        }

        // Validate report type against whitelist
        String[] validTypes = {"summary", "detailed", "audit", "compliance"};
        boolean validType = false;
        for (String vt : validTypes) {
            if (vt.equals(reportType)) { validType = true; break; }
        }
        if (!validType) {
            resp.sendError(400, "Invalid report type: " + safeType);
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String query;
            if (department != null && !department.isEmpty()) {
                // Department filter uses parameterized base but dynamic ORDER BY
                query = "SELECT employee_id, full_name, department, report_date, amount "
                      + "FROM expense_reports "
                      + "WHERE report_type = ? AND report_date BETWEEN ? AND ? "
                      + "AND department = '" + department + "' "
                      + "ORDER BY report_date DESC";
            } else {
                query = "SELECT employee_id, full_name, department, report_date, amount "
                      + "FROM expense_reports "
                      + "WHERE report_type = ? AND report_date BETWEEN ? AND ? "
                      + "ORDER BY report_date DESC";
            }

            log.info("Executing report query for type=" + safeType + " dept=" + safeDept);

            PreparedStatement stmt = conn.prepareStatement(query);
            stmt.setString(1, reportType);
            stmt.setString(2, startDate);
            stmt.setString(3, endDate);

            ResultSet rs = stmt.executeQuery();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("{\"results\":[");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",");
                out.printf("{\"id\":\"%s\",\"name\":\"%s\",\"dept\":\"%s\",\"date\":\"%s\",\"amount\":%.2f}",
                    rs.getString(1), rs.getString(2), rs.getString(3),
                    rs.getString(4), rs.getDouble(5));
                first = false;
            }
            out.print("]}");
            out.flush();
        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal server error");
        }
    }
}
